import csv,re
D='/projectnb/jbrcs/mangband/Advisor/studies/2026-09-29-messages/scratch/'
inp={r['id']:r for r in csv.DictReader(open(D+'M5_input.csv'))}
PH={'<item>':r'(?P<item>.+?)','<name>':r'(?P<name>.+?)','<n>':r'(?P<n>\d+)','<mon>':r'(?P<mon>.+?)','<x>':r'(?P<x>.+?)','<ch>':r'(?P<ch>.+?)','<verb>':r'(?P<verb>\w+)','<msg>':r'(?P<msg>.*)','<c>':r'(?P<c>.)','<pty>':r'(?P<pty>.+?)','<feel>':r'(?P<feel>.+?)','<use>':r'(?P<use>.+?)','<slot>':r'(?P<slot>.)','<sender>':r'(?P<sender>.+?)'}
def rx(t):
    parts=re.split('(<[a-z]+>)',t); o=''
    for p in parts:
        o+= PH[p] if p in PH else re.escape(p)
    return '^'+o+'$'
rows=[]
def add(i,text,event,aud,rel,cond,notes='',regex=None):
    r=inp[str(i)]
    rows.append(dict(id=i,file=r['file'],line=r['line'],text=text,event=event,audience=aud,pilot_relevance=rel,regex=regex if regex is not None else (rx(text) if text else ''),condition=cond,notes=notes))
DEAD='dead code'
def dead(i,text,why,ev='dead.code'):
    add(i,text,ev,'self','none',why,'Not reachable in the shipped server.',regex='')
